nta.declaration:
// ============================================================
// Continuous RSU based autonomous intersection model
// ============================================================
// Main idea:
// - Main street: EAST-WEST
// - Side street: NORTH-SOUTH
// - RSU controls the intersection
// - M/M/1: only one vehicle can cross
// - M/M/2: two vehicles can cross only if they are non-conflicting
// - Priority:
//      1. Emergency vehicle
//      2. Main street vehicles
//      3. Side street vehicles
//      4. Right turn before left turn in a conflict
// - Communication:
//      V2I: vehicle requests RSU
//      I2V: RSU sends emergency yield broadcast
//      V2V: vehicles broadcast enter/leave message
// - Continuous arrival:
//      after leaving, every vehicle comes again after its period
// ============================================================

const int N = 6;

// This file is fixed for M/M/1 mode
const int MM1 = 1;
const int MM2 = 2;
const int MM_MODE = MM1;

// Directions
const int EAST  = 0;
const int WEST  = 1;
const int NORTH = 2;
const int SOUTH = 3;

// Turn types
const int RIGHT    = 0;
const int STRAIGHT = 1;
const int LEFT     = 2;

// V2I / I2V / V2V communication
chan req[N];        // V2I: normal vehicle -> RSU
chan emg_req[N];    // V2I: emergency vehicle -> RSU
chan grant[N];      // I2V: RSU -> vehicle
chan leave[N];      // vehicle -> RSU after leaving

broadcast chan i2v_yield;  // RSU tells nearby vehicles to yield for emergency
broadcast chan v2v_enter;  // vehicle announces entering intersection
broadcast chan v2v_leave;  // vehicle announces leaving intersection

// Queue and crossing state
bool waiting[N];
bool crossing[N];

int[0,3] origin[N];
int[0,2] turn[N];
int[0,1] emergency[N];

int[0,2] crossingCount = 0;
bool emergencyNotified = false;

// ------------------------------------------------------------
// Helper functions
// ------------------------------------------------------------

bool isMainRoad(int i)
{
    return origin[i] == EAST || origin[i] == WEST;
}

bool oppositeDirection(int a, int b)
{
    if (origin[a] == EAST  && origin[b] == WEST)  return true;
    if (origin[a] == WEST  && origin[b] == EAST)  return true;
    if (origin[a] == NORTH && origin[b] == SOUTH) return true;
    if (origin[a] == SOUTH && origin[b] == NORTH) return true;
    return false;
}

int turnRank(int i)
{
    if (turn[i] == RIGHT) return 0;
    if (turn[i] == STRAIGHT) return 1;
    return 2;
}

int priorityValue(int i)
{
    // Emergency has highest priority.
    if (emergency[i] == 1) return 0;

    // Main street has higher priority than side street.
    if (isMainRoad(i)) {
        return 10 + turnRank(i);
    }

    return 20 + turnRank(i);
}

bool betterPriority(int a, int b)
{
    int pa;
    int pb;

    pa = priorityValue(a);
    pb = priorityValue(b);

    if (pa < pb) return true;
    if (pa > pb) return false;

    // Tie breaker: lower ID first.
    // This keeps the state space small and avoids infinite FIFO counters.
    return a < b;
}

// ------------------------------------------------------------
// Conflict checking
// ------------------------------------------------------------

bool conflict(int a, int b)
{
    if (a == b) return false;

    // Emergency vehicle gets exclusive crossing permission.
    if (emergency[a] == 1 || emergency[b] == 1) return true;

    // Same origin cannot enter together.
    if (origin[a] == origin[b]) return true;

    // Opposite-direction vehicles can sometimes pass together.
    if (oppositeDirection(a, b)) {

        // Both straight from opposite sides are allowed together.
        if (turn[a] == STRAIGHT && turn[b] == STRAIGHT) return false;

        // Both right turns from opposite sides are allowed together.
        if (turn[a] == RIGHT && turn[b] == RIGHT) return false;

        // Critical scenario:
        // North-right versus South-left, or generally right versus left.
        // They are not allowed together.
        if (turn[a] == RIGHT && turn[b] == LEFT) return true;
        if (turn[a] == LEFT && turn[b] == RIGHT) return true;

        // Any left-turn conflict is blocked for safety.
        if (turn[a] == LEFT || turn[b] == LEFT) return true;

        return false;
    }

    // Perpendicular movements are considered conflicting.
    return true;
}

bool conflictsWithCrossing(int i)
{
    int k;

    for (k = 0; k < N; k++) {
        if (crossing[k] && conflict(i, k)) {
            return true;
        }
    }

    return false;
}

bool noCollision()
{
    int i;
    int j;

    for (i = 0; i < N; i++) {
        for (j = i + 1; j < N; j++) {
            if (crossing[i] && crossing[j] && conflict(i, j)) {
                return false;
            }
        }
    }

    return true;
}

// ------------------------------------------------------------
// Queue and grant logic
// ------------------------------------------------------------

bool emergencyWaiting()
{
    int k;

    for (k = 0; k < N; k++) {
        if (waiting[k] && emergency[k] == 1) {
            return true;
        }
    }

    return false;
}

bool capacityAvailableFor(int i)
{
    if (MM_MODE == MM1) {
        return crossingCount == 0;
    }

    // M/M/2 mode
    if (crossingCount >= 2) return false;

    return !conflictsWithCrossing(i);
}

bool existsBetterGrantable(int i)
{
    int k;

    for (k = 0; k < N; k++) {
        if (waiting[k] && k != i && betterPriority(k, i)) {
            if (capacityAvailableFor(k)) {
                return true;
            }
        }
    }

    return false;
}

bool canGrant(int i)
{
    if (!waiting[i]) return false;

    // If emergency is waiting, no normal vehicle receives a new grant.
    if (emergencyWaiting() && emergency[i] == 0) return false;

    if (!capacityAvailableFor(i)) return false;

    if (existsBetterGrantable(i)) return false;

    return true;
}

// ------------------------------------------------------------
// State update functions
// ------------------------------------------------------------

void requestVehicle(int i, int o, int t, int e)
{
    origin[i] = o;
    turn[i] = t;
    emergency[i] = e;

    waiting[i] = true;
}

void grantVehicle(int i)
{
    waiting[i] = false;
    crossing[i] = true;
    crossingCount = crossingCount + 1;

    if (emergency[i] == 1) {
        emergencyNotified = false;
    }
}

void finishVehicle(int i)
{
    crossing[i] = false;

    if (crossingCount > 0) {
        crossingCount = crossingCount - 1;
    }
}

nta.system:
// Vehicle(id, origin, turn, emergency, arrival_period, crossing_time)
//
// V0 = emergency vehicle on main street
// V1/V2 = main street straight vehicles, useful for M/M/2 non-conflict test
// V3 = side street straight
// V4 = North right turn
// V5 = South left turn
//
// Critical scenario:
// V4 wants to turn right from North.
// V5 wants to turn left from South.
// They must not cross together.

RSU = RSU_Controller();

V0 = Vehicle(0, EAST,  STRAIGHT, 1, 30, 4); // emergency vehicle
V1 = Vehicle(1, EAST,  STRAIGHT, 0, 6,  5); // main street
V2 = Vehicle(2, WEST,  STRAIGHT, 0, 8,  5); // main street opposite
V3 = Vehicle(3, NORTH, STRAIGHT, 0, 10, 5); // side street
V4 = Vehicle(4, NORTH, RIGHT,    0, 12, 5); // critical right-turn vehicle
V5 = Vehicle(5, SOUTH, LEFT,     0, 12, 5); // critical left-turn vehicle

system RSU, V0, V1, V2, V3, V4, V5;
